bool stratum_subscribe(struct pool *pool) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;
    char url[256];
    char json_req[1024];
    char *resp = NULL;
    size_t resp_len = 0;
    cJSON *json, *result, *session_id, *nonce;

    if (!pool || !pool->url || !pool->user || !pool->pass) {
        return false;
    }

    snprintf(url, sizeof(url), "%s://%s:%d", "http", pool->host, pool->port);

    curl = curl_easy_init();
    if (!curl) {
        return false;
    }

    headers = curl_slist_append(headers, "Content-Type: application/json");
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

    snprintf(json_req, sizeof(json_req),
             "{"
             "  \"jsonrpc\": \"2.0\","
             "  \"method\": \"mining.subscribe\","
             "  \"params\": [\"%s\"],"
             "  \"id\": 1"
             "}",
             "miner-subscriber");

    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_req);

    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, &write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &resp_len);
    curl_easy_setopt(curl, CURLOPT_WRITEHEADER, NULL);

    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
        return false;
    }

    curl_easy_cleanup(curl);
    curl_slist_free_all(headers);

    json = cJSON_Parse(resp);
    if (!json) {
        free(resp);
        return false;
    }

    result = cJSON_GetObjectItemCaseSensitive(json, "result");
    if (!result || !cJSON_IsArray(result)) {
        cJSON_Delete(json);
        free(resp);
        return false;
    }

    session_id = cJSON_GetArrayItemCaseSensitive(result, 0);
    nonce = cJSON_GetArrayItemCaseSensitive(result, 1);

    if (!session_id || !nonce || !cJSON_IsString(session_id) || !cJSON_IsString(nonce)) {
        cJSON_Delete(json);
        free(resp);
        return false;
    }

    strncpy(pool->session_id, session_id->valuestring, sizeof(pool->session_id) - 1);
    strncpy(pool->nonce, nonce->valuestring, sizeof(pool->nonce) - 1);

    cJSON_Delete(json);
    free(resp);

    return true;
}

bool stratum_subscribe(struct pool *pool) {
    CURL *curl = curl_easy_init();
    bool success = false;
    char *json_response = NULL;
    cJSON *json_request = NULL, *json_result = NULL;
    char *request_str = NULL;

    if (!curl) {
        applog(LOG_ERR, "Failed to initialize CURL for Stratum subscription");
        goto out;
    }

    // Construct JSON-RPC subscription request
    json_request = cJSON_CreateObject();
    cJSON_AddItemToObject(json_request, "jsonrpc", cJSON_CreateString("2.0"));
    cJSON_AddItemToObject(json_request, "method", cJSON_CreateString("mining.subscribe"));
    cJSON_AddItemToObject(json_request, "params", cJSON_CreateArray());
    cJSON_AddItemToObject(json_request, "id", cJSON_CreateNumber(1));

    request_str = cJSON_PrintUnformatted(json_request);

    if (!request_str) {
        applog(LOG_ERR, "Failed to serialize JSON for Stratum subscription");
        goto out;
    }

    curl_easy_setopt(curl, CURLOPT_URL, pool->stratum_url);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, request_str);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, curl_slist_append(NULL, "Content-Type: application/json"));

    // Perform request and capture response (omitted for brevity)

    // Assume json_response is parsed and contains session ID and nonce
    json_result = cJSON_Parse(json_response);
    if (!json_result) {
        applog(LOG_ERR, "Failed to parse JSON response from Stratum pool");
        goto out;
    }

    // Extract session ID and nonce from JSON response
    cJSON *session_id = cJSON_GetObjectItemCaseSensitive(json_result, "session_id");
    cJSON *nonce = cJSON_GetObjectItemCaseSensitive(json_result, "nonce");

    if (!session_id || !nonce) {
        applog(LOG_ERR, "Stratum response missing session ID or nonce");
        goto out;
    }

    strcpy(pool->session_id, session_id->valuestring);
    strcpy(pool->nonce, nonce->valuestring);

    success = true;

out:
    if (json_request)
        cJSON_Delete(json_request);
    if (json_result)
        cJSON_Delete(json_result);
    if (request_str)
        free(request_str);
    if (json_response)
        free(json_response);

    if (curl)
        curl_easy_cleanup(curl);

    return success;
}

bool stratum_subscribe(struct pool *pool) {
