        return false;

    CURLcode res;
    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        curl_easy_cleanup(curl);
        return false;
    }

    char json_request[512];
    snprintf(json_request, sizeof(json_request),
        "{"
            "\"jsonrpc\": \"2.0\","
            "\"method\": \"mining.subscribe\","
            "\"params\": [],"
            "\"id\": 1"
        "}");

    curl_easy_setopt(curl, CURLOPT_URL, pool->stratum_url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_request);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, pool->write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, pool);

    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Stratum subscription failed: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
        return false;
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);

    // Assume the response processing is handled via pool->write_callback
    if (!pool->session_id || !pool->nonce) {
        return false;
    }

    // Update the pool state and log session details
    pool->is_subscribed = true;
    printf("Stratum session initiated: Session ID=%s, Nonce=%s\n", pool->session_id, pool->nonce);
    return true;
}

bool stratum_subscribe(struct pool *pool) {
    CURL *curl = curl_easy_init();
    if (!curl)
        return false;

    char *json_request = NULL;
    size_t json_len = 0;

    // Construct the JSON-RPC subscription request
    asprintf(&json_request, "{"
                  "\"jsonrpc\": \"2.0\","
                  "\"method\": \"mining.subscribe\","
                  "\"params\": [\"%s\"],"
                  "\"id\": 1"
                  "}",
            pool->user);

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    curl_easy_setopt(curl, CURLOPT_URL, pool->stratum_url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_request);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_request));
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, pool);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        log_error("Stratum subscription failed: %s", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        free(json_request);
        return false;
    }

    // Process the JSON response to extract session ID and nonce
    cJSON *response = cJSON_Parse(pool->stratum_response);
    if (!response) {
        log_error("Failed to parse Stratum response");
        curl_easy_cleanup(curl);
        free(json_request);
        return false;
    }

    cJSON *result = cJSON_GetObjectItemCaseSensitive(response, "result");
    if (!result || !result->valuearray || cJSON_GetArraySize(result) < 3) {
        log_error("Invalid Stratum response format");
        cJSON_Delete(response);
        curl_easy_cleanup(curl);
        free(json_request);
        return false;
    }

    cJSON *session_id = cJSON_GetArrayItemCaseSensitive(result, 0);
    cJSON *nonce = cJSON_GetArrayItemCaseSensitive(result, 1);
    cJSON *nnonce = cJSON_GetArrayItemCaseSensitive(result, 2);

    if (!session_id || !nonce || !nonsense || !session_id->valuestring || !nonce->valuestring || !nonsense->valuestring) {
        log_error("Incomplete Stratum subscription response");
        cJSON_Delete(response);
        curl_easy_cleanup(curl);
        free(json_request);
        return false;
    }

    // Update pool state with session ID and nonce
    strcpy(pool->session_id, session_id->valuestring);
    strcpy(pool->nonce, nonce->valuestring);
    strcpy(pool->nonsense, nonsense->valuestring);

    cJSON_Delete(response);
    curl_easy_cleanup(curl);
    free(json_request);

    log_info("Stratum session initiated: session_id=%s, nonce=%s", pool->session_id, pool->nonce);
    return true;
}

bool stratum_subscribe(struct pool* pool) {
    CURL* curl;
    CURLcode res;
    struct curl_response response = {0};

    if (!pool || !pool->url)
        return false;

    curl = curl_easy_init();
    if (!curl)
        return false;

    json_t* json = json_object();
    if (!json)
        return false;

    json_object_set_new(json, "method", json_string("mining.subscribe"));
    json_object_set_new(json, "params", json_array());
    json_object_set_new(json, "id", json_integer(1));

    curl_easy_setopt(curl, CURLOPT_URL, pool->url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_dumps(json, 0));
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, curl_write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);

    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        applog(LOG_ERR, "Stratum subscribe failed: %s", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        json_decref(json);
        return false;
    }

    curl_easy_cleanup(curl);
    json_decref(json);

    json_t* json_response = json.loads(response.buffer);
    if (!json_response) {
        applog(LOG_ERR, "Failed to parse stratum subscription response");
        free(response.buffer);
        return false;
    }

    json_t* result = json_object_get(json_response, "result");
    if (!result || !json_is_array(result) || json_array_size(result) < 2) {
        applog(LOG_ERR, "Invalid stratum subscription response format");
        json_decref(json_response);
        free(response.buffer);
        return false;
    }

    json_t* session_id = json_array_get(result, 0);
    json_t* nonce = json_array_get(result, 1);

    if (!json_is_string(session_id) || !json_is_string(nonce)) {
        applog(LOG_ERR, "Invalid stratum subscription result format");
        json_decref(json_response);
        free(response.buffer);
        return false;
    }

    strncpy(pool->session_id, json_string_value(session_id), sizeof(pool->session_id) - 1);
    strncpy(pool->nonce, json_string_value(nonce), sizeof(pool->nonce) - 1);
    pool->session_active = true;

    applog(LOG_INFO, "Stratum session initiated - session_id: %s, nonce: %s", pool->session_id, pool->nonce);

    json_decref(json_response);
    free(response.buffer);
    return true;
}
